#include "Vdss_v2_early_single_sa_wrapper.h"
#include <iostream>
#include <string>
namespace {
int failures=0;
void eq(const std::string&c,const char*f,unsigned e,unsigned a){if(e==a)return;++failures;std::cout<<"FAIL case="<<c<<"\nfield="<<f<<"\nexpected="<<e<<"\nactual="<<a<<"\n";}
void run(Vdss_v2_early_single_sa_wrapper&d,const char*n,unsigned sa,unsigned v,unsigned rel,unsigned bor,unsigned cfg,unsigned pat,unsigned donor,unsigned release){d.sa_id_i=sa;d.local_accept_i=v;d.released_i=rel;d.borrowed_i=bor;d.borrower_id_flat_i=0;d.pattern_flat_i=0x4321;d.eval();std::cout<<"CASE "<<n<<" sa="<<sa<<" local=0x"<<std::hex<<v<<" released=0x"<<rel<<" borrowed=0x"<<bor<<std::dec<<"\n";eq(n,"selected_valid",1,d.selected_valid_o);eq(n,"selected_config_id",cfg,d.selected_config_o);eq(n,"selected_pattern_id",pat,d.selected_pattern_o);const unsigned needs_donor=(cfg==2||cfg==3||cfg==5||cfg==6);eq(n,"selected_donor_valid",needs_donor,d.donor_valid_o);if(d.donor_valid_o)eq(n,"selected_donor_resource",donor,d.donor_o);eq(n,"release_required",release,d.release_o);}
}
int main(){Vdss_v2_early_single_sa_wrapper d;run(d,"A_CFG0_LOCAL",0,1,0,0,0,1,0,0);run(d,"A_CFG4_RELEASE",0,2,0,0,4,2,2,1);run(d,"A_CFG5_BORROW_PRIMARY",0,4,4,0,5,3,2,0);run(d,"A_CFG6_RELEASE_BORROW",0,8,4,0,6,4,2,1);run(d,"A_BORROW_FALLBACK",0,4,8,0,5,3,3,0);run(d,"B_CFG0_LOCAL",1,1,0,0,0,1,0,0);run(d,"B_CFG2_OVER_CFG1_PRIORITY",1,6,1,0,2,3,0,0);run(d,"B_CFG1_RELEASE",1,2,0,0,1,2,0,1);run(d,"B_CFG2_BORROW_PRIMARY",1,4,1,0,2,3,0,0);run(d,"B_BORROW_FALLBACK",1,4,2,0,2,3,1,0);run(d,"B_CFG3_RELEASE_BORROW",1,8,1,0,3,4,0,1);
d.sa_id_i=1;d.local_accept_i=6;d.released_i=0;d.borrowed_i=0;d.borrower_id_flat_i=0;d.pattern_flat_i=0x4321;d.eval();std::cout<<"CASE B_PHYSICAL_FEASIBILITY_FALLBACK sa=1 local=0x6 released=0x0 borrowed=0x0\n";eq("B_PHYSICAL_FEASIBILITY_FALLBACK","CFG2_local_accept",1,(d.local_accept_i>>2)&1);eq("B_PHYSICAL_FEASIBILITY_FALLBACK","CFG2_physical_feasible",0,(d.physical_feasible_o>>2)&1);eq("B_PHYSICAL_FEASIBILITY_FALLBACK","CFG1_local_accept",1,(d.local_accept_i>>1)&1);eq("B_PHYSICAL_FEASIBILITY_FALLBACK","CFG1_physical_feasible",1,(d.physical_feasible_o>>1)&1);eq("B_PHYSICAL_FEASIBILITY_FALLBACK","selected_valid",1,d.selected_valid_o);eq("B_PHYSICAL_FEASIBILITY_FALLBACK","selected_config_id",1,d.selected_config_o);eq("B_PHYSICAL_FEASIBILITY_FALLBACK","selected_pattern_id",2,d.selected_pattern_o);std::cout<<"DIRECTED_FAILURE_COUNT = "<<failures<<"\n";return failures?1:0;}
